/** @param {{des: object}} api */
export default function Wiz_fila({ des }) {
    des.room({
        type: 'ordinary',
        contents: () => {
            des.stair('up');
            des.object();
            des.monster({ 'class': 'i', peaceful: 0 });
        },
    });

    des.room({
        type: 'ordinary',
        contents: () => {
            des.object();
            des.object();
            des.monster({ 'class': 'i', peaceful: 0 });
        },
    });

    des.room({
        type: 'ordinary',
        contents: () => {
            des.object();
            des.trap();
            des.object();
            des.monster('vampire bat');
            des.monster('vampire bat');
        },
    });

    des.room({
        type: 'ordinary',
        contents: () => {
            des.stair('down');
            des.object();
            des.trap();
            des.monster({ 'class': 'i', peaceful: 0 });
            des.monster('vampire bat');
        },
    });

    des.room({
        type: 'ordinary',
        contents: () => {
            des.object();
            des.object();
            des.trap();
            des.monster({ 'class': 'i', peaceful: 0 });
        },
    });

    des.room({
        type: 'ordinary',
        contents: () => {
            des.object();
            des.trap();
            des.monster('vampire bat');
        },
    });

    des.random_corridors();
}
